//=====================================================================
//  anlogic_logo_rom.v —— 安路 Logo 点阵只读存储器（160x160，25 位/像素）
//---------------------------------------------------------------------
//  ★2026-10-09 改版：由「组合 case」改为「同步读（地址打 1 拍）」。
//
//  为什么要改（实测证据，2026-10-09 18:41 布局布线报告）：
//    6400 条 case 被综合成 ~13 级 LUT mux 树；旧写法在 hdmi_mixer 里把
//    「区域比较 + 坐标减法 + S_logo_y*LOGO_W（被推成 DSPMULT）+ 加法」
//    与这 13 级 mux 串在同一拍，直通输出寄存器 O_hdmi_data_reg[..]，
//    总 Logic-Level = 15、Max-Fanout = 113
//    ==> slow_m40c 下 setup 违例（WNS -0.083ns，净延迟占 53%）。
//
//  改后时序（延迟不变，仍是与像素对齐的 2 拍流水）：
//    第 1 拍：(S_x_1d,S_y_1d) -> 区域比较 / 坐标减法 / 移位加法 -> 本 ROM 地址
//              （≈5 级，且 160 = 128+32 用两次左移相加，无乘法器）
//    第 2 拍：本 ROM 已寄存的输出 -> alpha 判定 -> 叠加 mux -> 输出寄存器
//              （≈3 级）
//    对齐依据：t 边沿采样 S_x_1d = X0 的同时 S_x_2d 更新为 X0
//              ==> 本拍 ROM 输出对应像素 X0，与本拍 S_x_2d / 像素数据同像素。
//
//  ★★ 2026-10-11 改版（v2，面积优化）：case → ERAM 数组
//---------------------------------------------------------------------
//  问题：TD 综合报 u_anlogic_logo_rom = 1,970 LUT（占全设计 8.7%），
//        是 6400 条并行 case 比较器。全设计 LUT 22,717 / 上限 21,216 → 超 1,501。
//  处置：把「组合 case」改成「(* ram_style = "block" *) 数组 + 同步读」，
//        让 TD 把它推断进 ERAM（块 RAM），不再占 LUT。
//
//  ⚠ 时序与功能**完全等价**，理由：
//    · 原写法：always @(posedge I_clk) case(I_addr) ... O_pixel = ...; endcase
//      —— 也是「地址打 1 拍」的同步读，1 拍延迟。
//    · 新写法：always @(posedge I_clk) O_pixel <= mem[I_addr];
//      —— 同样是 1 拍延迟，时序行为逐拍一致。
//    · 位级对拍：tb_logo_rom_equiv.v 对 20427 个地址逐点比对（含未初始化项 → 0）。
//
//  ⚠ 地址空间 = 0 ~ 20426（稀疏，实际非空 6387 项）。
//    数组按**满地址空间**开，是为了 hdmi_mixer 的地址换算一个字都不用改。
//    代价：510675 bit ≈ 24.9 块 ERAM20K（器件 108 块，改前已用 43 块 → 余量充足）。
//=====================================================================
module anlogic_logo_rom (
    input  wire        I_clk,    // ★同步读时钟（HDMI 像素时钟域）
    input  wire [14:0] I_addr,
    output reg  [24:0] O_pixel
);

    // ★ 强制进 ERAM（块 RAM）。写法与工程内 sobel_3x3.v 一致。
    //   若 TD 不认 block，可改 "bram"（TD IP 里用的是这个）。
    (* ram_style = "block" *) reg [24:0] mem [0:20426];

    // 上电初始化：6387 条有效项，其余保持 0（与 case 的 default 一致）
    integer i;
    initial begin
        for (i = 0; i <= 20426; i = i + 1) mem[i] = 25'd0;
        mem[5494] = 25'h1d3d4d8;
        mem[5499] = 25'h1fcd5d5;
        mem[5500] = 25'h1f88688;
        mem[5501] = 25'h1f77e81;
        mem[5502] = 25'h1f77e81;
        mem[5503] = 25'h1f77e81;
        mem[5504] = 25'h1f77e81;
